package com.tnr.cityguide.auth;

import com.tnr.cityguide.config.AppProperties;
import com.tnr.cityguide.user.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.*;
import java.util.*;
import org.springframework.core.env.Environment;
import org.springframework.http.HttpStatus;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class AuthService {
 private static final String DUMMY_HASH="$2a$12$C6UzMDM.H6dfI/f/IKcEe.8KxwLZ5fQm9W9QJQ9fQ1zZ2l4G9n4r2K";
 private final UserRepository users;private final RefreshTokenRepository refresh;private final PasswordResetTokenRepository resets;private final PasswordEncoder encoder;private final JwtService jwt;private final LoginAttemptService attempts;private final MailService mail;private final AppProperties props;private final Clock clock;private final Environment environment;private final SecureRandom random=new SecureRandom();
 public AuthService(UserRepository users,RefreshTokenRepository refresh,PasswordResetTokenRepository resets,PasswordEncoder encoder,JwtService jwt,LoginAttemptService attempts,MailService mail,AppProperties props,Clock clock,Environment environment){this.users=users;this.refresh=refresh;this.resets=resets;this.encoder=encoder;this.jwt=jwt;this.attempts=attempts;this.mail=mail;this.props=props;this.clock=clock;this.environment=environment;}
 @Transactional public AuthDtos.AuthResponse register(AuthDtos.RegisterRequest r){String email=normal(r.email());Map<String,String> errors=new LinkedHashMap<>();if(r.name()==null||r.name().trim().length()<2)errors.put("name","Please enter your full name.");if(!validEmail(email))errors.put("email","Enter a valid email address.");else if(users.existsByEmailIgnoreCase(email))errors.put("email","An account with this email already exists.");String pw=passwordMessage(r.password());if(pw!=null)errors.put("password",pw);if(!Objects.equals(r.password(),r.confirmPassword()))errors.put("confirm","Passwords do not match.");if(!errors.isEmpty())throw new FieldValidationException(errors);User u=new User();u.setName(r.name().trim());u.setEmail(email);u.setPasswordHash(encoder.encode(r.password()));u.setRole(Role.USER);users.save(u);return issue(u);}
 @Transactional public AuthDtos.AuthResponse login(AuthDtos.LoginRequest r){if(r==null||!validEmail(normal(r.email()))||r.password()==null||r.password().isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Enter your email and password");String email=normal(r.email());if(attempts.isLocked(email)){int n=attempts.secondsLeft(email);throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Too many attempts. Try again in "+n+"s.");}User user=users.findByEmailIgnoreCase(email).orElse(null);String hash=user==null?DUMMY_HASH:user.getPasswordHash();if(!encoder.matches(r.password(),hash)){attempts.failed(email);if(attempts.isLocked(email)){int n=attempts.secondsLeft(email);throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Too many attempts. Try again in "+n+"s.");}throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Incorrect email or password.");}attempts.success(email);return issue(user);}
 @Transactional public AuthDtos.AuthResponse refresh(String token){String hash=sha(token);RefreshToken row=refresh.findByTokenHash(hash).orElseThrow(this::expired);if(row.isRevoked()){refresh.revokeAll(row.getUser().getId());throw expired();}if(row.getExpiresAt().isBefore(clock.instant())){row.setRevoked(true);throw expired();}User user=users.findById(row.getUser().getId()).orElseThrow(this::expired);row.setRevoked(true);return issue(user);}
 @Transactional public void logout(String token){if(token!=null)refresh.findByTokenHash(sha(token)).ifPresent(t->t.setRevoked(true));}
 @Transactional public Map<String,Object> forgot(String email){String normalized=normal(email);if(!validEmail(normalized))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Enter a valid email address.");String[] codeOut={null};users.findByEmailIgnoreCase(normalized).ifPresent(user->{resets.findByUserIdAndUsedAtIsNull(user.getId()).forEach(t->t.setUsedAt(clock.instant()));String code=String.format("%06d",100000+random.nextInt(900000));codeOut[0]=code;PasswordResetToken token=new PasswordResetToken();token.setUser(user);token.setTokenHash(sha(code));token.setExpiresAt(clock.instant().plus(Duration.ofMinutes(props.reset().codeTtlMinutes())));resets.save(token);mail.sendPasswordResetCode(normalized,code);});Map<String,Object> response=new LinkedHashMap<>();response.put("message","If an account exists, a code has been sent.");if(props.dev().returnResetCode()&&Arrays.asList(environment.getActiveProfiles()).contains("local")&&codeOut[0]!=null)response.put("devCode",codeOut[0]);return response;}
 @Transactional public void reset(AuthDtos.ResetRequest r){String email=normal(r.email());User user=users.findByEmailIgnoreCase(email).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"This code has expired. Request a new one."));PasswordResetToken token=resets.findByUserIdAndUsedAtIsNull(user.getId()).stream().max(Comparator.comparing(PasswordResetToken::getExpiresAt)).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"This code has expired. Request a new one."));if(token.getExpiresAt().isBefore(clock.instant())||token.getAttempts()>=props.reset().maxAttempts())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"This code has expired. Request a new one.");if(!MessageDigest.isEqual(token.getTokenHash().getBytes(StandardCharsets.UTF_8),sha(r.code()).getBytes(StandardCharsets.UTF_8))){token.setAttempts(token.getAttempts()+1);if(token.getAttempts()>=props.reset().maxAttempts())token.setUsedAt(clock.instant());throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"The code is incorrect.");}String problem=passwordMessage(r.password());if(problem!=null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,problem);if(!Objects.equals(r.password(),r.confirmPassword()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Passwords do not match.");token.setUsedAt(clock.instant());user.setPasswordHash(encoder.encode(r.password()));refresh.revokeAll(user.getId());}
 @Transactional public AuthDtos.AuthResponse issueFresh(UUID userId){return issue(users.findById(userId).orElseThrow(this::expired));}
 private AuthDtos.AuthResponse issue(User user){String raw=newToken();RefreshToken token=new RefreshToken();token.setUser(user);token.setTokenHash(sha(raw));token.setExpiresAt(clock.instant().plus(props.jwt().refreshTtl()));refresh.save(token);return new AuthDtos.AuthResponse(jwt.accessToken(user),raw,"Bearer",jwt.expiresIn(),userDto(user));}
 private AuthDtos.UserDto userDto(User u){return new AuthDtos.UserDto(u.getId(),u.getName(),u.getEmail(),u.getPhone(),u.getAvatarUrl(),u.getRole().name(),new AuthDtos.Prefs(u.isNotifEvents(),u.isNotifReviews(),u.isNotifNews()));}
 private String newToken(){byte[] b=new byte[32];random.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}
 private String normal(String v){return v==null?"":v.trim().toLowerCase(Locale.ROOT);}
 private boolean validEmail(String v){return v.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");}
 private String passwordMessage(String p){if(p==null)p="";List<String> missing=new ArrayList<>();if(p.length()<8)missing.add("at least 8 characters");if(!p.matches(".*[A-Z].*"))missing.add("an uppercase letter");if(!p.matches(".*[a-z].*"))missing.add("a lowercase letter");if(!p.matches(".*\\d.*"))missing.add("a number");return missing.isEmpty()?null:"Password needs "+String.join(", ",missing)+".";}
 private String sha(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((value==null?"":value).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private ResponseStatusException expired(){return new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Session expired. Please log in again.");}
}
